import { useState, useEffect, Children, isValidElement, cloneElement } from "react";
import { useTheme } from "@theme";

import { ChartProps, LineProps } from "../chart.types";

export const useLineChart = ({ data: initialData, children }: ChartProps) => {
  const theme = useTheme();
  const [chartData, setChartData] = useState(initialData);

  useEffect(() => {
    setChartData(initialData);
  }, [initialData]);

  if (!theme) {
    return {
      chartData: initialData,
      numCategoricalColors: 0,
      numLines: 0,
      childrenWithProps: children,
    };
  }

  const categoricalColorKeys = Object.keys(theme.color.data.categorical).filter((key) =>
    key.endsWith("Default"),
  );
  const numCategoricalColors = categoricalColorKeys.length;

  const countLines = (children: React.ReactNode): number => {
    return Children.toArray(children).reduce((acc: number, child) => {
      if (isValidElement(child)) {
        if ((child.type as { displayName?: string })?.displayName === "Line") {
          acc += 1;
        }
      }
      return acc;
    }, 0);
  };

  const numLines = countLines(children);
  let lineIndex = 0;

  const childrenWithProps = Children.map(children, (child) => {
    if (isValidElement(child) && (child.type as { displayName?: string })?.displayName === "Line") {
      const clonedElement = cloneElement(child as React.ReactElement<LineProps>, {
        lineIndex: lineIndex++,
        ...child.props,
      });
      return clonedElement;
    }
    return child;
  });

  return {
    chartData,
    numCategoricalColors,
    numLines,
    childrenWithProps,
  };
};
